def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    ideal_remaining = 0.1
    width = 0.2
    score = 1.0 - np.abs(remaining - ideal_remaining) / width
    return np.where(remaining >= 0, np.maximum(score, 0.0), -np.inf)
